 IF (
WITH RECURSIVE functions AS (
    SELECT p.* FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname='public' AND p.proname IN('guard_product_edit_receipt_v1','bump_product_edit_revision_v1','assert_product_edit_actor_v1','product_edit_snapshot_v1','read_product_for_edit_v1','apply_product_edit_v1')
), receipt AS (SELECT 'public.product_edit_receipts'::regclass::oid AS oid),
triggers AS (SELECT t.* FROM pg_catalog.pg_trigger t WHERE t.tgrelid=(SELECT oid FROM receipt)
    OR (t.tgrelid='public.product_variants'::regclass AND t.tgname='product_variants_edit_revision')
    OR (t.tgrelid='public.product_options'::regclass AND t.tgname='product_options_edit_revision')),
objects AS (
    SELECT 'pg_catalog.pg_proc'::regclass::oid AS classid,oid AS objid FROM functions
    UNION SELECT 'pg_catalog.pg_class'::regclass::oid,oid FROM receipt
    UNION SELECT 'pg_catalog.pg_class'::regclass::oid,indexrelid FROM pg_catalog.pg_index WHERE indrelid=(SELECT oid FROM receipt)
    UNION SELECT 'pg_catalog.pg_trigger'::regclass::oid,oid FROM triggers
    UNION SELECT 'pg_catalog.pg_constraint'::regclass::oid,oid FROM pg_catalog.pg_constraint WHERE conrelid=(SELECT oid FROM receipt)
    UNION SELECT 'pg_catalog.pg_policy'::regclass::oid,oid FROM pg_catalog.pg_policy WHERE polrelid=(SELECT oid FROM receipt)
    UNION SELECT 'pg_catalog.pg_attrdef'::regclass::oid,oid FROM pg_catalog.pg_attrdef WHERE adrelid=(SELECT oid FROM receipt)
    UNION SELECT 'pg_catalog.pg_rewrite'::regclass::oid,oid FROM pg_catalog.pg_rewrite WHERE ev_class=(SELECT oid FROM receipt)
),
internal_footprint AS (SELECT classid,objid FROM objects UNION SELECT d.classid,d.objid FROM pg_catalog.pg_depend d JOIN internal_footprint o ON d.refclassid=o.classid AND d.refobjid=o.objid WHERE d.deptype='i'),
full_footprint AS (SELECT classid,objid FROM internal_footprint UNION SELECT 'pg_catalog.pg_class'::regclass::oid,i.indexrelid FROM pg_catalog.pg_index i WHERE i.indrelid=(SELECT reltoastrelid FROM pg_catalog.pg_class WHERE oid=(SELECT oid FROM receipt)))
SELECT
 EXISTS(SELECT 1 FROM pg_catalog.pg_depend d WHERE (d.refclassid,d.refobjid) IN(SELECT * FROM full_footprint) AND (d.classid,d.objid) NOT IN(SELECT * FROM full_footprint))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_depend d WHERE (d.classid,d.objid) IN(SELECT * FROM full_footprint) AND (d.classid,d.objid) NOT IN(SELECT * FROM objects) AND NOT ((d.deptype='i' AND (d.refclassid,d.refobjid) IN(SELECT * FROM full_footprint)) OR (d.deptype='a' AND d.classid='pg_catalog.pg_class'::regclass AND d.objid IN(SELECT indexrelid FROM pg_catalog.pg_index WHERE indrelid=(SELECT reltoastrelid FROM pg_catalog.pg_class WHERE oid=(SELECT oid FROM receipt))) AND d.refclassid='pg_catalog.pg_class'::regclass AND d.refobjid=(SELECT reltoastrelid FROM pg_catalog.pg_class WHERE oid=(SELECT oid FROM receipt)))))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_description d WHERE (d.classoid,d.objoid) IN(SELECT * FROM full_footprint) AND (d.classoid,d.objoid) NOT IN(SELECT * FROM objects))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_seclabel d WHERE (d.classoid,d.objoid) IN(SELECT * FROM full_footprint) AND (d.classoid,d.objoid) NOT IN(SELECT * FROM objects))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_shdepend d WHERE d.dbid=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database()) AND (d.classid,d.objid) IN(SELECT * FROM full_footprint) AND (d.classid,d.objid) NOT IN(SELECT * FROM objects) AND NOT(d.deptype='o' AND d.refclassid='pg_catalog.pg_authid'::regclass AND d.refobjid=pg_catalog.to_regrole(current_user)))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_type t WHERE ('pg_catalog.pg_type'::regclass::oid,t.oid) IN(SELECT * FROM full_footprint) AND (t.typowner IS DISTINCT FROM pg_catalog.to_regrole(current_user) OR t.typnamespace IS DISTINCT FROM 'public'::regnamespace OR t.typacl IS NOT NULL OR NOT t.typisdefined OR t.typnotnull OR t.typbasetype<>0 OR t.typdefault IS NOT NULL OR t.typdefaultbin IS NOT NULL OR NOT((t.oid=(SELECT reltype FROM pg_catalog.pg_class WHERE oid=(SELECT oid FROM receipt)) AND t.typtype='c' AND t.typrelid=(SELECT oid FROM receipt) AND t.typelem=0) OR (t.oid=(SELECT typarray FROM pg_catalog.pg_type WHERE oid=(SELECT reltype FROM pg_catalog.pg_class WHERE oid=(SELECT oid FROM receipt))) AND t.typtype='b' AND t.typrelid=0 AND t.typelem=(SELECT reltype FROM pg_catalog.pg_class WHERE oid=(SELECT oid FROM receipt))))))
 ) THEN RAISE EXCEPTION 'rollback346 refuses unknown dependent of owned row/array/toast objects'; END IF;
 IF EXISTS(SELECT 1 FROM public.product_edit_receipts) THEN RAISE EXCEPTION 'rollback346 refuses retained product edit receipts; use a reviewed forward repair'; END IF;
END $rollback_retention_profile$;

